#!/bin/sh
# Drop a "forgotten" database backup at a guessable path, built from the
# run-time flag. Common names devs leave behind: backup.sql, db_backup.sql,
# site-backup.zip, www.tar.gz — this one is /backups/db_backup.sql.
set -e
: "${CHAL_FLAG:?CHAL_FLAG must be provided}"
mkdir -p /usr/share/nginx/html/backups
cat > /usr/share/nginx/html/backups/db_backup.sql <<EOF
-- Pearl Telecom self-care DB dump (pre-migration snapshot)
-- generated by nightly cron, kept "just in case"
CREATE TABLE subscribers (id INT, msisdn VARCHAR(15), plan VARCHAR(32));
INSERT INTO subscribers VALUES (1,'0771234567','prepaid-lite');
INSERT INTO subscribers VALUES (2,'0759988776','postpaid-max');

CREATE TABLE app_config (k VARCHAR(64), v VARCHAR(128));
INSERT INTO app_config VALUES ('build_flag','${CHAL_FLAG}');
INSERT INTO app_config VALUES ('smtp_pass','p3arlT3l3c0m!');
EOF
